          static_cast<unsigned long long>(total.pib_occupancy_cycle_sum));
  fprintf(fout, "DTC_L1_pib_occupancy_sample_cycles = %llu\n",
          static_cast<unsigned long long>(total.pib_occupancy_sample_cycles));
